/**
 * The 254 Texas county outlines, as SVG path data on a 980x760 viewBox.
 *
 * Extracted verbatim from the prototype's `D.paths`. Keys are county names in the
 * prototype's own casing; `countyPathKey()` normalises the upper-case names the
 * operator API returns onto them.
 *
 * WHY IT IS ITS OWN MODULE. This is 63 KB of geometry and it is the same for
 * every operator. Keeping it separate means it is imported only by the map, and —
 * because the map's paths are server-rendered into the HTML rather than shipped as
 * props — it never enters a client bundle.
 */

export const TEXAS_VIEWBOX = { width: 980, height: 760 } as const;

/** County name (as the API spells it, upper case) -> the key used below. */
export function countyPathKey(apiCountyName: string): string {
  const wanted = apiCountyName.trim().toUpperCase();
  return (
    TEXAS_COUNTY_NAMES.find((name) => name.toUpperCase() === wanted) ?? ""
  );
}

